<template><main class="history-page"><header class="history-header"><button @click="router.back()"><van-icon name="arrow-left"/> 返回</button><div><p>READING TIMELINE</p><h1>浏览历史</h1></div><button class="clear" :disabled="!items.length" @click="clearAll"><van-icon name="delete-o"/> 清空</button></header><section class="history-hero"><p>YOUR NEWS JOURNEY</p><strong>{{ items.length }}</strong><em>条浏览记录</em><small>每次进入新闻详情都会自动记录；再次浏览同一篇文章会移到最前面。</small></section><section v-if="items.length" class="history-list"><article v-for="(item,index) in items" :key="item.id" class="history-card" @click="open(item)"><span class="number">{{String(index + 1).padStart(2, '0')}}</span><img :src="item.image||picture(item.id)" :alt="translateTitle(item.title)" @error="imageError($event,item.id)"/><div><p>{{translateSource(item.author||item.source||'新闻资讯')}} · {{item.publishTime||'实时更新'}}</p><h2>{{translateTitle(item.title)}}</h2><small>浏览于 {{item.viewTime}}</small></div><button class="remove" :aria-label="`删除浏览记录：${item.title}`" @click.stop="remove(item.id)"><van-icon name="cross"/></button></article></section><section v-else class="history-empty"><van-icon name="clock-o"/><h2>还没有浏览记录</h2><p>阅读新闻详情后，它会自动出现在这里。</p><button @click="router.push('/home')">去看新闻</button></section></main></template>
<script setup>import{computed,onMounted}from'vue';import{useRouter}from'vue-router';import{showDialog,showToast}from'vant';import{useHistoryStore}from'../store/modules/history';import{translateSource,translateTitle}from'../utils/newsTranslation';const router=useRouter(),store=useHistoryStore(),items=computed(()=>store.getHistory);const picture=id=>`https://picsum.photos/seed/nova-history-${encodeURIComponent(id)}/720/480`;const imageError=(event,id)=>event.target.src=picture(`${id}-alternate`);const open=item=>{if(item?.isLive)sessionStorage.setItem(`live-news:${item.id}`,JSON.stringify(item));router.push(`/news/detail/${item.id}`)};const remove=id=>{store.removeHistory(id);store.removeHistoryApi(id).catch(()=>{});showToast({message:'已移除浏览记录',position:'bottom'})};const clearAll=async()=>{try{await showDialog({title:'清空浏览历史',message:'确定清空全部浏览记录吗？',showCancelButton:true,className:'archive-dialog'});store.clearHistory();store.clearHistoryApi().catch(()=>{});showToast({message:'浏览历史已清空',position:'bottom'})}catch(_){}};onMounted(()=>store.loadHistory())</script>
<style scoped>.history-page{min-height:100vh;padding:0 clamp(22px,7vw,132px) 76px;color:#edf3ff;background:radial-gradient(circle at 95% 8%,#16546a 0,transparent 34%),radial-gradient(circle at 10% 0,#62419a 0,transparent 34%),#090d1b}.history-header{height:92px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;border-bottom:1px solid rgba(255,255,255,.12)}.history-header h1{margin:2px 0 0;font-size:23px;text-align:center}.history-header p,.history-hero p{font-size:11px;letter-spacing:2px;color:#9ee9ff}.history-header p{text-align:center}.history-header button{border:0;background:transparent;color:#d8e8fc;font-size:14px;justify-self:start}.history-header .clear{justify-self:end;color:#a9e8ff}.history-header .clear:disabled{opacity:.35}.history-hero{margin:36px 0 26px;padding:30px 34px;border:1px solid rgba(193,221,255,.18);border-radius:25px;background:linear-gradient(120deg,rgba(47,32,89,.66),rgba(17,58,77,.69));box-shadow:inset 0 1px rgba(255,255,255,.12),0 18px 45px rgba(0,0,0,.2);backdrop-filter:blur(20px)}.history-hero strong{display:inline-block;margin-top:7px;font-size:54px;line-height:1;color:#fff}.history-hero em{font-style:normal;margin-left:10px;color:#cad5ee}.history-hero small{display:block;margin-top:16px;color:#adbed6}.history-list{display:grid;gap:13px}.history-card{position:relative;display:grid;grid-template-columns:154px 1fr;gap:18px;align-items:center;min-height:132px;padding:13px 62px 13px 13px;overflow:hidden;cursor:pointer;border:1px solid rgba(204,224,255,.16);border-radius:20px;background:rgba(255,255,255,.065);box-shadow:0 15px 32px rgba(0,0,0,.16);transition:transform .2s,border-color .2s;backdrop-filter:blur(14px)}.history-card:hover{transform:translateX(4px);border-color:rgba(150,225,255,.5)}.history-card img{width:154px;height:105px;object-fit:cover;border-radius:13px}.history-card p{font-size:11px;color:#9de3f9}.history-card h2{margin:7px 0 10px;font-size:18px;line-height:1.42}.history-card small{font-size:11px;color:#a6b3cc}.number{position:absolute;z-index:1;top:23px;left:23px;border-radius:7px;padding:3px 6px;background:rgba(8,14,31,.7);font-size:10px;font-weight:800}.remove{position:absolute;right:20px;top:50%;width:33px;height:33px;transform:translateY(-50%);border:1px solid rgba(255,255,255,.35);border-radius:50%;color:#fff;background:rgba(15,19,38,.64);opacity:0;transition:opacity .2s,background .2s}.history-card:hover .remove,.remove:focus{opacity:1}.remove:hover{background:#ec466e}.history-empty{max-width:560px;margin:84px auto;padding:54px 35px;text-align:center;border:1px solid rgba(189,219,255,.18);border-radius:25px;background:rgba(255,255,255,.055);backdrop-filter:blur(18px)}.history-empty :deep(.van-icon){font-size:40px;color:#88dfff}.history-empty h2{margin:14px 0 8px}.history-empty p{color:#b0bed2}.history-empty button{margin-top:22px;padding:10px 17px;border:0;border-radius:11px;color:#fff;background:linear-gradient(135deg,#4d99b5,#8154d7)}@media(max-width:600px){.history-page{padding:0 18px 76px}.history-header{height:76px}.history-header h1{font-size:19px}.history-hero{margin-top:22px;padding:25px}.history-hero strong{font-size:45px}.history-card{grid-template-columns:105px 1fr;gap:12px;min-height:108px;padding-right:48px}.history-card img{width:105px;height:80px}.history-card h2{font-size:15px}.remove{right:12px;opacity:1}}
</style>
